import{_ as o,l as r,o as e,c as n,v as l,p as s,x as t,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const L=JSON.parse('{"title":"VLM 幻觉与 POPE","description":"","frontmatter":{"title":"VLM 幻觉与 POPE","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/vlm-hallucination.md","filePath":"llm/vlm-hallucination.md","lastUpdated":1789023840000}'),P={name:"llm/vlm-hallucination.md"};function c(h,a,m,u,_,A){const i=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="vlm-幻觉与-pope" tabindex="-1">VLM 幻觉与 POPE <a class="header-anchor" href="#vlm-幻觉与-pope" aria-label="Permalink to &quot;VLM 幻觉与 POPE&quot;">​</a></h1><div class="epigraph"><p>语言模型擅长把「像有」说圆。视觉前缀若只提供主题级证据，物体名词会从语言先验里补出来。</p><footer>—— Li 等 Evaluating Object Hallucination in Large Vision-Language Models（POPE）</footer></div><p><a href="/llm/visual-instruction-data">上一课</a>让模型敢谈图。主干<a href="/llm/hallucination-taxonomy">幻觉分类</a>写的是文本侧假话类型。本课缺口是视觉特有的物体幻觉：图中没有的东西被说成有。后课定位默认：只靠「是/否有某物」不够，还要把名词钉到格子上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>开放描述的奖励是流畅与覆盖。指令数据里常见「图中有……」句式，语言模型会把共现物体写进回答——厕所场景就「有洗手台」，即使 <a href="/llm/vit-as-encoder">ViT</a> 的 patch 没提供该证据。这与 CLIP 全局向量对不上细物体是同一病：对比空间与标题先验都偏名词，不偏「不存在」。</p><p>自由描述难以自动判假。POPE（Polling-based Object Probing Evaluation）改成探测：对图问「图中有 {object} 吗？」正例来自真实标注物体，负例来自随机、流行或对抗共现。准确率、精确率、召回、Yes 比率分开报——Yes 偏高就是乱认。</p><p><span class="marginnote">POPE 测的是物体有无，不是属性、计数、关系。描述里编造颜色或「三只」仍可在 POPE 上及格。不要用它替代 OCR 与指代评测。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>训练侧：在指令里加入否定与拒答、降低无根据列举、用存在性问答做辅助损失。解码侧：降低鼓励覆盖的采样，或对物体名词做与视觉一致的约束（后课 grounding 更硬）。评测必须含 POPE 三类负例，且与自由描述的人评分列。不要用 <a href="/llm/clip">CLIP</a> 余弦当「没幻觉」的证明。</p>',9)),(e(),s(E,null,{default:t(()=>[p(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20DESC%5B%22%E5%BC%80%E6%94%BE%E6%8F%8F%E8%BF%B0%22%5D%20--%3E%20PRIOR%5B%22%E8%AF%AD%E8%A8%80%E7%89%A9%E4%BD%93%E5%85%88%E9%AA%8C%22%5D%0A%20%20PRIOR%20--%3E%20HALL%5B%22%E7%BC%96%E9%80%A0%E7%89%A9%E4%BD%93%22%5D%0A%20%20PROBE%5B%22POPE%20%E6%98%AF%E5%90%A6%E9%A2%98%22%5D%20--%3E%20YN%5B%22%E6%9C%89%E6%97%A0%E5%88%A4%E5%86%B3%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>因果 LLM 在视觉前缀之后继续写，每一步仍是词表 softmax。若视觉键值对「有没有猫」区分弱，而「室内、沙发」强烈激活猫的语言共现，Yes 与名词就会被先验带走。<a href="/llm/llava-projector">LLaVA 投影器</a> 越浅、ViT 越冻，这个通道越依赖 CLIP 已经提取的概念，未提取的细物更容易被语言补全。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>压幻觉会伤召回：模型改口说「看不清」。下一课把问题改成指代与框，让「说有」必须对应空间证据。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>物体幻觉是语言先验在弱视觉证据上补名词。</li><li>POPE 用是否探测把描述不可判变成可自动评。</li><li>Yes 比率与精确率要一起看。</li><li>出处：Li 等 POPE；指令来源见 LLaVA。</li></ul>',6))])}const O=o(P,[["render",c]]);export{L as __pageData,O as default};
